 return '<section class="cg-trust-section" id="case-study"><div class="wrap"><p class="eyebrow">'+eyebrow+'</p><h1>Fresh Perch Limited</h1><h2>'+title+'</h2><p>'+p1+'</p><p>'+p2+'</p><p><strong>Verified Trade Passport: UG-CG-0003</strong></p><div class="actions"><a class="btn primary" href="#passport-sample">Read the passport sample (EN) →</a><a class="btn secondary" href="'+prefix+'contact.html?subject=Fresh%20Perch%20Limited%20Trade%20Passport#enquiry">'+cta+' →</a></div><p class="cg-trust-note">'+note+'</p></div></section>'

