   s=re.sub(r'<body([^>]*)>',lambda m:'<body'+re.sub(r'class="([^"]*)"',lambda c:'class="'+c[1]+' cg-unified-brand"',m[1])+'>' if 'class=' in m[1] else '<body'+m[1]+' class="cg-unified-brand">',s,count=1)
